self.KB_CONTENT["card:778945"]={"id":"card:778945","ty":"card","sourceId":"778945","title":"『商品包裝資料建立作業』中的『大箱包材淨重 (ML013)』為何？","ver":"GP4以上","topic":"包裝","keywords":["包裝","商品"],"y":"other","answer":"* 滿大箱重量=大箱包材淨重+(1大箱小箱數*滿小箱重量)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
