self.KB_CONTENT["card:782320"]={"id":"card:782320","ty":"card","sourceId":"782320","title":"『應收票據票貼整批作業』中的『輸入票貼銀行』為何？","ver":"GP4以上","topic":"票據","keywords":["票據","銀行","應收","整批"],"y":"other","answer":"* 輸入票據欲由哪家銀行做票貼。* 可點選(icon)或[F2]銀行資料查詢，不可空白。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
