self.KB_CONTENT["card:777650"]={"id":"card:777650","ty":"card","sourceId":"777650","title":"『託外進貨單建立作業』中的『保稅碼 (TH037)』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","品號","保稅"],"y":"other","answer":"* 區分0.依品號預設、Y.預設為保稅品及N.預設為非保稅品。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
