self.KB_CONTENT["card:753177"]={"id":"card:753177","ty":"card","sourceId":"753177","title":"『客戶訂單F/O明細表』中的『列印單價金額』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","客戶","訂單","權限"],"y":"other","answer":"* 預設為勾選。* 若無售價權限者，此選項則預設為未勾選且不可作修改。※ 訂單預計出貨明細表","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
